// Fetch approved experience from database
// report_id comes from the review workflow trigger
const body = $input.first().json;
const reportId = body.report_id;

if (!reportId) {
  throw new Error('report_id is required');
}

return {
  report_id: reportId,
  reviewer_id: body.reviewer_id || '',
};

// Build structured knowledge text from experience report
const row = $input.first().json;

// Handle Postgres result format (may be row object or rows array)
const report = row.rows ? row.rows[0] : row;

if (!report) {
  throw new Error('Report not found or not approved');
}

// Structure the experience as instructional knowledge
const structuredText = `【经验案例】
故障现象：${report.fault_description}

解决方案：${report.solution}

适用机型：${report.machine_type || '通用'}

提交人ID：${report.user_id}
审核状态：已审核通过

---
详细操作步骤：${report.solution}`;

return {
  report_id: report.id,
  title: report.title,
  user_id: report.user_id,
  machine_type: report.machine_type || '',
  full_text: structuredText,
  fault_description: report.fault_description,
  solution: report.solution,
  ingest_id: 'exp_' + report.id,
};

// Prepare chunks for batch embedding
const result = $input.first().json;
const chunks = result.chunks || [];
const expData = $('Structure Experience').first().json;

return chunks.map(chunk => ({
  chunk_index: chunk.chunk_index,
  text: chunk.text,
  ingest_id: expData.ingest_id,
  report_id: expData.report_id,
  title: expData.title,
  machine_type: expData.machine_type,
  user_id: expData.user_id,
}));

// Batch embed all chunk texts
const items = $input.all();
const texts = items.map(item => item.json.text);

return {
  texts,
  item_count: items.length,
  ingest_id: items[0]?.json?.ingest_id,
  report_id: items[0]?.json?.report_id,
  title: items[0]?.json?.title,
  machine_type: items[0]?.json?.machine_type,
  user_id: items[0]?.json?.user_id,
};

// Assemble Qdrant points with experience metadata
const embedResult = $input.first().json;
const embeddings = embedResult.embeddings || [];
const chunkItems = $('Prepare Items').all();
const meta = $('Build Embed Batch').first().json;

const points = chunkItems.map((item, i) => ({
  id: item.json.ingest_id + '_' + item.json.chunk_index,
  vector: embeddings[i] || [],
  payload: {
    doc_type: 'experience',
    machine_type: item.json.machine_type,
    category: 'troubleshooting',
    chunk_text: item.json.text,
    chunk_index: item.json.chunk_index,
    source_title: item.json.title,
    report_id: item.json.report_id,
    submitted_by: item.json.user_id,
    ingest_id: item.json.ingest_id,
    created_at: new Date().toISOString(),
  }
}));

return {
  points,
  point_count: points.length,
  report_id: meta.report_id,
  title: meta.title,
};

// Build final response
const meta = $('Assemble Qdrant Points').first().json;

return {
  status: 'ok',
  message: '经验知识已入库',
  report_id: meta.report_id,
  title: meta.title,
  chunk_count: meta.point_count,
};
